
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_llp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_llp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.465201923971870e+01, 9.098409394798796e+01, 8.596768501907030e+01, 7.925630160836359e+01, 7.055530207178715e+01, 5.976925365604251e+01, 4.722084224029212e+01, 3.386698325149375e+01, 2.130871397863374e+01, 1.132961047630556e+01, 5.036273177534461e+00, 2.543569610916081e+00, 1.917496612556602e+00, 1.275526644540620e+00, 6.433021806848608e-01, 2.423578177644131e-01, 6.834678432514514e-02, 1.394029035706132e-02, 1.884883514143394e-03, 1.444439971971913e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


